#include <stdio.h>

static int sum(const int values[], int length)
{
    int total = 0;
    for (int index = 0; index < length; ++index) {
        total += values[index];
    }
    return total;
}

int main(void)
{
    const int readings[] = {5, 8, 2};
    int capacity = (int)(sizeof readings / sizeof readings[0]);
    printf("%d\n", sum(readings, capacity));
    printf("%d\n", sum(readings, 0));
    return 0;
}

